    isValidErrno, getErrno, resetErrno, errnoToIOError, throwErrno,
    throwErrnoIf, throwErrnoIf_, throwErrnoIfRetry, throwErrnoIfRetry_,
    throwErrnoIfMinus1, throwErrnoIfMinus1_, throwErrnoIfMinus1Retry,
    throwErrnoIfMinus1Retry_, throwErrnoIfNull, throwErrnoIfNullRetry,
    throwErrnoIfRetryMayBlock, throwErrnoIfRetryMayBlock_,
    throwErrnoIfMinus1RetryMayBlock, throwErrnoIfMinus1RetryMayBlock_,
    throwErrnoIfNullRetryMayBlock,
    throwErrnoPath, throwErrnoPathIf, throwErrnoPathIf_,
    throwErrnoPathIfNull, throwErrnoPathIfMinus1, throwErrnoPathIfMinus1_
  ) where

import ForeignPrims
import IOPrims (primStdin)
import IOBase (Handle(..))
import PreludeIO (IOError(..))
import Foreign.Ptr
import Foreign.C.Types

newtype Errno = Errno CInt

instance Eq Errno where
  e1@(Errno n1) == e2@(Errno n2)
    | isValidErrno e1 && isValidErrno e2 = n1 == n2
    | otherwise                          = False

isValidErrno :: Errno -> Bool
isValidErrno (Errno n) = n /= -1

errno :: String -> Errno
errno name = Errno (fromIntegral (primErrnoValue name))

eOK :: Errno
eOK = Errno 0

