getErrno :: IO Errno
getErrno = do
  n <- primGetErrno
  return (Errno (fromIntegral n))

resetErrno :: IO ()
resetErrno = primSetErrno 0

-- An IOError for the errno, its kind as GHC classifies it and its
-- description strerror's.
errnoToIOError :: String -> Errno -> Maybe Handle -> Maybe String -> IOError
errnoToIOError loc (Errno n) mh mpath =
  IOError (primErrnoIOError loc (fromIntegral n)
                            (isJust' mh) (handleObj mh)
                            (isJust' mpath) (maybe "" id mpath))
  where isJust' (Just _) = True
        isJust' Nothing  = False
        handleObj (Just (Handle h)) = h
        handleObj Nothing           = primStdin   -- unused

throwErrno :: String -> IO a
throwErrno loc = do
  e <- getErrno
  ioError (errnoToIOError loc e Nothing Nothing)

throwErrnoIf :: (a -> Bool) -> String -> IO a -> IO a
throwErrnoIf failed loc act = do
  r <- act
  if failed r then throwErrno loc else return r

throwErrnoIf_ :: (a -> Bool) -> String -> IO a -> IO ()
throwErrnoIf_ failed loc act = throwErrnoIf failed loc act >> return ()

-- The Retry forms repeat the action while it fails with EINTR.
throwErrnoIfRetry :: (a -> Bool) -> String -> IO a -> IO a
throwErrnoIfRetry failed loc act = do
  r <- act
  if failed r
    then do e <- getErrno
            if e == eINTR then throwErrnoIfRetry failed loc act
                          else throwErrno loc
    else return r

throwErrnoIfRetry_ :: (a -> Bool) -> String -> IO a -> IO ()
throwErrnoIfRetry_ failed loc act = throwErrnoIfRetry failed loc act >> return ()

-- The MayBlock forms also run on_block, then retry, when the action
-- fails with EAGAIN or EWOULDBLOCK.
throwErrnoIfRetryMayBlock :: (a -> Bool) -> String -> IO a -> IO b -> IO a
throwErrnoIfRetryMayBlock failed loc act onBlock = do
  r <- act
  if failed r
    then do e <- getErrno
            if e == eINTR
              then throwErrnoIfRetryMayBlock failed loc act onBlock
              else if e == eWOULDBLOCK || e == eAGAIN
                then onBlock >> throwErrnoIfRetryMayBlock failed loc act onBlock
                else throwErrno loc
    else return r

throwErrnoIfRetryMayBlock_ :: (a -> Bool) -> String -> IO a -> IO b -> IO ()
throwErrnoIfRetryMayBlock_ failed loc act onBlock =
  throwErrnoIfRetryMayBlock failed loc act onBlock >> return ()

throwErrnoIfMinus1 :: (Eq a, Num a) => String -> IO a -> IO a
throwErrnoIfMinus1 = throwErrnoIf (== -1)

throwErrnoIfMinus1_ :: (Eq a, Num a) => String -> IO a -> IO ()
throwErrnoIfMinus1_ = throwErrnoIf_ (== -1)

throwErrnoIfMinus1Retry :: (Eq a, Num a) => String -> IO a -> IO a
throwErrnoIfMinus1Retry = throwErrnoIfRetry (== -1)

throwErrnoIfMinus1Retry_ :: (Eq a, Num a) => String -> IO a -> IO ()
throwErrnoIfMinus1Retry_ = throwErrnoIfRetry_ (== -1)

throwErrnoIfMinus1RetryMayBlock :: (Eq a, Num a) => String -> IO a -> IO b -> IO a
throwErrnoIfMinus1RetryMayBlock = throwErrnoIfRetryMayBlock (== -1)

throwErrnoIfMinus1RetryMayBlock_ :: (Eq a, Num a) => String -> IO a -> IO b -> IO ()
throwErrnoIfMinus1RetryMayBlock_ = throwErrnoIfRetryMayBlock_ (== -1)

throwErrnoIfNull :: String -> IO (Ptr a) -> IO (Ptr a)
throwErrnoIfNull = throwErrnoIf (== nullPtr)

throwErrnoIfNullRetry :: String -> IO (Ptr a) -> IO (Ptr a)
throwErrnoIfNullRetry = throwErrnoIfRetry (== nullPtr)

throwErrnoIfNullRetryMayBlock :: String -> IO (Ptr a) -> IO b -> IO (Ptr a)
throwErrnoIfNullRetryMayBlock = throwErrnoIfRetryMayBlock (== nullPtr)

-- The Path forms name the file in the IOError.
throwErrnoPath :: String -> FilePath -> IO a
throwErrnoPath loc path = do
  e <- getErrno
  ioError (errnoToIOError loc e Nothing (Just path))

throwErrnoPathIf :: (a -> Bool) -> String -> FilePath -> IO a -> IO a
throwErrnoPathIf failed loc path act = do
  r <- act
  if failed r then throwErrnoPath loc path else return r

throwErrnoPathIf_ :: (a -> Bool) -> String -> FilePath -> IO a -> IO ()
throwErrnoPathIf_ failed loc path act = throwErrnoPathIf failed loc path act >> return ()

throwErrnoPathIfNull :: String -> FilePath -> IO (Ptr a) -> IO (Ptr a)
throwErrnoPathIfNull = throwErrnoPathIf (== nullPtr)

throwErrnoPathIfMinus1 :: (Eq a, Num a) => String -> FilePath -> IO a -> IO a
throwErrnoPathIfMinus1 = throwErrnoPathIf (== -1)

throwErrnoPathIfMinus1_ :: (Eq a, Num a) => String -> FilePath -> IO a -> IO ()
throwErrnoPathIfMinus1_ = throwErrnoPathIf_ (== -1)
